/*Table structure for table `analizadores` */

DROP TABLE IF EXISTS `analizadores`;

CREATE TABLE `analizadores` (
  `id_analizadores` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `tag` varchar(50) NOT NULL,
  `linea` varchar(4) DEFAULT NULL,
  `tipo_analizador` varchar(15) DEFAULT NULL,
  `descripcion` varchar(100) DEFAULT NULL,
  `marca` varchar(100) DEFAULT NULL,
  `modelo` varchar(100) DEFAULT NULL,
  `extractivo` varchar(4) DEFAULT NULL,
  `rango_medida` varchar(10) DEFAULT NULL,
  `unidad` varchar(10) DEFAULT NULL,
  `incertidumbre_equipo` varchar(10) DEFAULT NULL,
  `func_calibracion` varchar(10) DEFAULT NULL,
  `senyal_salida` varchar(10) DEFAULT NULL,
  `control_emisiones` varchar(4) DEFAULT NULL,
  `tag_senyal_de_control` varchar(4) DEFAULT NULL,
  `correccion_humedad` varchar(4) DEFAULT NULL,
  `correccion_oxigeno` varchar(4) DEFAULT NULL,
  `limite_alarma_dcs` varchar(10) DEFAULT NULL,
  `valor_limite_emision` varchar(10) DEFAULT NULL,
  `limite_legal_diario` varchar(10) DEFAULT NULL,
  `fecha_instalacion` datetime DEFAULT NULL,
  `fecha_ult_revision` datetime DEFAULT NULL,
  `estado` enum('OPERATIVO','MANTENIMIENTO','AVERIADO','INVENTARIO','RETIRADO') DEFAULT NULL,
  `observaciones` longtext DEFAULT NULL,
  PRIMARY KEY (`id_analizadores`)
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8;

